// 1. Obtener la respuesta de texto de Gemini
const rawText = $input.item.json.content.parts[0].text;

// 2. Limpiar los bloques de Markdown ```json y ```
const cleanJsonText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

// 3. Convertir el texto a un Objeto JSON de JavaScript
const parsedData = JSON.parse(cleanJsonText);

// 4. Retornar los datos limpios
return {
  json: {
    reference: parsedData.reference,
    amount: parseFloat(parsedData.amount)
  }
};

// El backend responde { accounts: [...] } en un solo item. Se expande a un
// item por buzón para que el resto del flujo procese cada local por separado.
const res = $input.first().json || {};
const cuentas = res.accounts || [];

if (!Array.isArray(cuentas) || cuentas.length === 0) {
  return [];   // ningún local con correo vinculado → el ciclo termina aquí
}

return cuentas.map(c => ({ json: c }));

// Ancla de contexto de la rama Gmail. Los nodos HTTP pierden los campos del
// item de entrada, así que los nodos siguientes recuperan el local y el token
// desde aquí por posición ($itemIndex), que n8n sí preserva.
return $input.all();

// Gmail responde { messages: [{id, threadId}] } por cada buzón consultado.
// Se expande a un item por mensaje, arrastrando el contexto del local.
const contextos = $('Gmail · Contexto').all();
const entradas = $input.all();
const salida = [];

for (let i = 0; i < entradas.length; i++) {
  const ctx = contextos[i]?.json || {};
  const mensajes = entradas[i].json?.messages || [];
  for (const m of mensajes) {
    salida.push({
      json: {
        message_id: m.id,
        local_slug: ctx.local_slug,
        access_token: ctx.access_token,
        // Checkpoint exacto del local. La búsqueda de Gmail trae de más a
        // propósito (ver 'Buzones vinculados'), así que el descarte fino se
        // hace en 'Parsear correo Gmail' contra este valor.
        since_epoch_ms: ctx.since_epoch_ms || 0,
      }
    });
  }
}

return salida;

// ── Parseo de notificaciones bancarias ──────────────────────────────────────
// Mismas reglas que el flujo original (monto con $, referencia por palabra
// clave, pagador por "de X en tu cuenta"), aplicables tanto al snippet de
// Gmail como al bodyPreview de Microsoft Graph.

const BANCOS = [
  [/bancolombia/i, 'Bancolombia'],
  [/davivienda/i, 'Davivienda'],
  [/bbva/i, 'BBVA'],
  [/bogota|bogotá/i, 'Banco de Bogotá'],
  [/nequi/i, 'Nequi'],
  [/daviplata/i, 'Daviplata'],
  [/occidente/i, 'Banco de Occidente'],
];

function detectarBanco(remitente, asunto) {
  const texto = `${remitente || ''} ${asunto || ''}`;
  for (const [re, nombre] of BANCOS) {
    if (re.test(texto)) return nombre;
  }
  // Default histórico del flujo: los correos vigilados eran de Bancolombia.
  return 'Bancolombia';
}

function parsearNotificacion({ texto, asunto, remitente, fecha, idFallback }) {
  const snippet = texto || '';

  // Monto: primer "$1.234.567" del cuerpo.
  let amount = 0;
  const amountMatch = snippet.match(/\$([\d.,]+)/);
  if (amountMatch) {
    amount = parseFloat(amountMatch[1].replace(/,/g, ''));
  }

  // Referencia: número que sigue a comprobante / referencia / aprobación.
  let reference = '';
  const refMatch = snippet.match(/(?:comprobante|referencia|aprobaci[óo]n)\s*#?\s*(\d+)/i);
  if (refMatch) {
    reference = refMatch[1];
  } else {
    // Sin referencia explícita se sintetiza una estable por mensaje, para que
    // el UNIQUE(local_id, reference, payment_date) del backend deduplique.
    reference = 'BC-MAIL-' + (idFallback || Math.random().toString(36).slice(2, 11));
  }

  let payerName = 'Desconocido';
  const nameMatch = snippet.match(/\bde\s+(.+?)\s+en\s+tu\s+cuenta/i);
  if (nameMatch) payerName = nameMatch[1].trim();

  return {
    reference,
    amount,
    bank: detectarBanco(remitente, asunto),
    payer_name: payerName,
    payment_date: (fecha instanceof Date && !isNaN(fecha) ? fecha : new Date()).toISOString(),
    email_subject: asunto || 'Sin asunto',
    raw_email: snippet,
  };
}

const contextos = $('Gmail · Expandir mensajes').all();
const entradas = $input.all();
const salida = [];

for (let i = 0; i < entradas.length; i++) {
  const ctx = contextos[i]?.json || {};
  const correo = entradas[i].json || {};
  const headers = correo.payload?.headers || [];

  const asunto = headers.find(h => h.name === 'Subject')?.value || 'Sin asunto';
  const remitente = headers.find(h => h.name === 'From')?.value || '';
  const fecha = correo.internalDate ? new Date(parseInt(correo.internalDate, 10)) : new Date();

  // Descarte exacto de lo ya procesado.
  //
  // El operador `after:` de Gmail no coincide con el internalDate del mensaje:
  // medido contra un buzón real, sigue devolviendo un correo hasta ~13 s
  // después de su propia marca de tiempo. Por eso el backend consulta desde
  // `checkpoint - margen` y el corte de verdad se hace aquí, contra el
  // timestamp real. Sin esto, el último correo procesado vuelve en cada ciclo.
  const desde = Number(ctx.since_epoch_ms) || 0;
  if (desde && fecha.getTime() <= desde) continue;

  const pago = parsearNotificacion({
    texto: correo.snippet || '',
    asunto,
    remitente,
    fecha,
    idFallback: correo.id || ctx.message_id,
  });

  // Sin monto no hay nada que cruzar contra el comprobante del cliente.
  if (!pago.amount) continue;

  salida.push({ json: { ...pago, local_slug: ctx.local_slug } });
}

return salida;

