// Graph responde { value: [ ...mensajes ] } por cada buzón consultado.
const contextos = $('Outlook · Contexto').all();
const entradas = $input.all();
const salida = [];

for (let i = 0; i < entradas.length; i++) {
  const ctx = contextos[i]?.json || {};
  const mensajes = entradas[i].json?.value || [];

  for (const correo of mensajes) {
    const fecha = correo.receivedDateTime ? new Date(correo.receivedDateTime) : new Date();

    // Mismo descarte exacto que en la rama de Gmail: la consulta a Graph
    // arranca antes del checkpoint a propósito, y el corte real va aquí.
    const desde = Number(ctx.since_epoch_ms) || 0;
    if (desde && fecha.getTime() <= desde) continue;

    const remitente = correo.from?.emailAddress?.address || '';
    const pago = parsearNotificacion({
      texto: correo.bodyPreview || '',
      asunto: correo.subject || 'Sin asunto',
      remitente,
      fecha,
      idFallback: correo.id,
    });

    if (!pago.amount) continue;

    salida.push({ json: { ...pago, local_slug: ctx.local_slug } });
  }
}

return salida;

// Avanza el checkpoint de cada local hasta el correo más reciente que sí se
// registró. Se corre DESPUÉS del registro: si el POST falla, el checkpoint no
// avanza y el correo se reintenta en el próximo ciclo (el UNIQUE del backend
// absorbe los duplicados).
const filas = $('Parsear correo Gmail').all();
const porLocal = {};

for (const fila of filas) {
  const slug = fila.json.local_slug;
  if (!slug) continue;
  const ms = new Date(fila.json.payment_date || Date.now()).getTime();
  porLocal[slug] = Math.max(porLocal[slug] || 0, ms);
}

// +1 s porque el operador `after:` de Gmail es inclusivo y volvería a traer
// el mismo correo en el siguiente poll.
return Object.entries(porLocal).map(([local_slug, ms]) => ({
  json: { local_slug, checked_at: new Date(ms + 1000).toISOString() }
}));

