const data = $json;
const text = String(data.raw_email || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const amountMatch = String(data.raw_email || '').match(/\$\s*([\d.,]+)/);
let amount = amountMatch ? amountMatch[1] : data.amount;
if (amount !== null && amount !== undefined) {
  amount = String(amount).replace(/[^0-9.,-]/g, '');
  const comma = amount.lastIndexOf(',');
  const dot = amount.lastIndexOf('.');
  amount = Number(comma > dot ? amount.replace(/\./g, '').replace(',', '.') : amount.replace(/,/g, ''));
}
const outgoing = /compraste|enviaste|transferiste|transferencia realizada|pago realizado|retiro|debito|debitado|salio de tu cuenta/.test(text);
const incoming = /recibiste|recibido|abono recibido|transferencia recibida|consignacion recibida|ingreso a tu cuenta|deposito recibido|se acredito/.test(text);
const direction = outgoing ? 'outgoing' : incoming ? 'incoming' : 'incoming';
